import java.util.Scanner;

public class Main {
    static final int MAXN = 1000111;
    static final long MOD = 1000000007;

    static long[] visited = new long[MAXN];
    static long[] countArray = new long[MAXN];

    static long binPow(long base, int power) {
        long res = 1;
        while (power > 0) {
            if ((power & 1) == 1) {
                res = (res * base) % MOD;
            }
            base = (base * base) % MOD;
            power >>= 1;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();

        if (k == 0) {
            System.out.println(binPow(p, p - 1));
            return;
        }
        if (k == 1) {
            System.out.println(binPow(p, p));
            return;
        }

        for (int i = 0; i < MAXN; i++) {
            visited[i] = 0;
            countArray[i] = 0;
        }

        for (int start = 1; start < p; start++) {
            if (visited[start] != 0) continue;
            long u = start;
            int length = 0;
            while (visited[(int) u] == 0) {
                visited[(int) u] = 1;
                u = (u * k) % p;
                length++;
            }
            countArray[length]++;
        }

        long answer = 1;
        for (int i = 1; i <= p - 1; i++) {
            if (countArray[i] == 0) continue;
            long tmp = binPow((i * countArray[i] + 1) % MOD, (int) countArray[i]);
            answer = (answer * tmp) % MOD;
        }

        System.out.println(answer);
        sc.close();
    }
}
